								q = 1 - noise
							}
							for i, mask := range []uint16{0, 1, 31, 511} {
								a, err := old.ForecastObserved(mask, x&mask)
								if err != nil {
									t.Fatal(err)
								}
								b, err := c.Forecast(mask, x&mask)
								if err != nil {
									t.Fatal(err)
								}
